//! Signal channel via signal-cli daemon HTTP/JSON-RPC.//!//! Connects to a running `signal-cli daemon --http <host:port>`.//! Listens for messages via SSE at `/api/v1/events` and sends via//! JSON-RPC at `/api/v1/rpc`.use std::num::NonZeroUsize;use std::sync::Arc;use std::sync::atomic::{AtomicBool, Ordering};use std::time::Duration;use async_trait::async_trait;use futures::StreamExt;use lru::LruCache;use reqwest::Client;use serde::Deserialize;use tokio::sync::RwLock;use uuid::Uuid;use crate::bootstrap::ironclaw_base_dir;use crate::channels::{Channel, IncomingMessage, MessageStream, OutgoingResponse, StatusUpdate};use crate::config::SignalConfig;use crate::error::ChannelError;use crate::pairing::PairingStore;const GROUP_TARGET_PREFIX: &str = "group:";const SIGNAL_HEALTH_ENDPOINT: &str = "/api/v1/check";const MAX_SSE_BUFFER_SIZE: usize = 1024 * 1024;const MAX_SSE_EVENT_SIZE: usize = 256 * 1024;const MAX_HTTP_RESPONSE_SIZE: usize = 10 * 1024 * 1024;const MAX_REPLY_TARGETS: usize = 10000;const MAX_ERROR_LOG_BODY: usize = 1024;const REPLY_TARGETS_CAP: NonZeroUsize = NonZeroUsize::new(MAX_REPLY_TARGETS).unwrap(); // safety: 10000 is nonzero/// Recipient classification for outbound messages.#[derive(Debug, Clone, PartialEq, Eq)]enum RecipientTarget {    Direct(String),    Group(String),}// ── signal-cli SSE event JSON shapes ────────────────────────────#[derive(Debug, Deserialize)]struct SseEnvelope {    #[serde(default)]    envelope: Option<Envelope>,}#[derive(Debug, Deserialize)]struct Envelope {    #[serde(default)]    source: Option<String>,    #[serde(rename = "sourceNumber", default)]    source_number: Option<String>,    #[serde(rename = "sourceName", default)]    source_name: Option<String>,    #[serde(rename = "sourceUuid", default)]    source_uuid: Option<String>,    #[serde(rename = "dataMessage", default)]    data_message: Option<DataMessage>,    #[serde(rename = "storyMessage", default)]    story_message: Option<serde_json::Value>,    #[serde(default)]    timestamp: Option<u64>,}#[derive(Debug, Deserialize)]struct DataMessage {    #[serde(default)]    message: Option<String>,    #[serde(default)]    timestamp: Option<u64>,    #[serde(rename = "groupInfo", default)]    group_info: Option<GroupInfo>,    #[serde(default)]    attachments: Option<Vec<serde_json::Value>>,}#[derive(Debug, Deserialize)]struct GroupInfo {    #[serde(rename = "groupId", default)]    group_id: Option<String>,}/// Signal channel using signal-cli daemon's native JSON-RPC + SSE API.pub struct SignalChannel {    config: SignalConfig,    client: Client,    /// LRU cache of reply targets per incoming message, used by `respond()`.    /// Bounded to `MAX_REPLY_TARGETS` entries; least-recently-used entries    /// are evicted automatically when the cache is full.    reply_targets: Arc<RwLock<LruCache<Uuid, String>>>,    /// Debug mode for verbose tool output (toggled via /debug command).    debug_mode: Arc<AtomicBool>,}impl SignalChannel {    /// Create a new Signal channel with normalized config and fresh client/cache.    pub fn new(config: SignalConfig) -> Result<Self, ChannelError> {        let mut config = config;        config.http_url = config.http_url.trim_end_matches('/').to_string();        let client = Client::builder()            .connect_timeout(Duration::from_secs(10))            .build()            .map_err(|e| ChannelError::Http(e.to_string()))?;        let cap = REPLY_TARGETS_CAP;        let reply_targets = Arc::new(RwLock::new(LruCache::new(cap)));        let debug_mode = Arc::new(AtomicBool::new(false));        Ok(Self::from_parts(config, client, reply_targets, debug_mode))    }    /// Construct a SignalChannel from pre-validated parts.    ///    /// Used by [`new()`][Self::new] after normalization and by [`sse_listener`]    /// to ensure both code paths use the same constructor.    fn from_parts(        config: SignalConfig,        client: Client,        reply_targets: Arc<RwLock<LruCache<Uuid, String>>>,        debug_mode: Arc<AtomicBool>,    ) -> Self {        Self {            config,            client,            reply_targets,            debug_mode,        }    }    fn is_debug(&self) -> bool {        self.debug_mode.load(Ordering::Relaxed)    }    fn toggle_debug(&self) -> bool {        let current = self.debug_mode.load(Ordering::Relaxed);        self.debug_mode.store(!current, Ordering::Relaxed);        !current    }    /// Effective sender: prefer `sourceNumber` (E.164), fall back to `source`    /// (UUID for privacy-enabled users).    fn sender(envelope: &Envelope) -> Option<String> {        envelope            .source_number            .as_deref()            .or(envelope.source.as_deref())            .map(String::from)    }    /// Normalize an allowlist entry to the bare identifier.    ///    /// Strips the `uuid:` prefix if present, so `uuid:<id>` and `<id>` both    /// match against a bare UUID sender.    fn normalize_allow_entry(entry: &str) -> &str {        entry.strip_prefix("uuid:").unwrap_or(entry)    }    /// Check whether a sender is in the allowed users list.    fn is_sender_allowed(&self, sender: &str) -> bool {        if self.config.allow_from.is_empty() {            return false;        }        self.config.allow_from.iter().any(|entry| {            entry == "*"                || Self::normalize_allow_entry(entry) == Self::normalize_allow_entry(sender)        })    }    /// Check if sender is allowed via config allow_from OR pairing store.    fn is_sender_allowed_with_pairing(&self, sender: &str) -> bool {        if self.is_sender_allowed(sender) {            return true;        }        let store = PairingStore::new();        if let Ok(allowed) = store.read_allow_from("signal") {            return allowed.iter().any(|entry| entry == "*" || entry == sender);        }        false    }    /// Handle pairing request for unapproved sender.    /// Returns Ok(true) if message should be allowed (was already paired),    /// Ok(false) if message was blocked but pairing request was processed.    fn handle_pairing_request(&self, sender: &str, source_name: Option<&str>) -> Result<bool, ()> {        let store = PairingStore::new();        let meta = serde_json::json!({            "sender": sender,            "name": source_name,        });        match store.upsert_request("signal", sender, Some(meta)) {            Ok(result) => {                tracing::info!(                    sender = %sender,                    code = %result.code,                    "Signal: pairing request upserted"                );                if result.created {                    let message = format!(                        "To pair with this bot, run: `ironclaw pairing approve signal {}`",                        result.code                    );                    let http_url = self.config.http_url.clone();                    let account = self.config.account.clone();                    let sender_owned = sender.to_string();                    let message_owned = message.clone();                    tokio::spawn(async move {                        if let Err(e) = Self::send_pairing_reply_async(                            &http_url,                            &account,                            &sender_owned,                            &message_owned,                        )                        .await                        {                            tracing::error!(sender = %sender_owned, error = %e, "Signal: failed to send pairing reply");                        }                    });                }                Ok(false)            }            Err(e) => {                tracing::error!(sender = %sender, error = %e, "Signal: pairing upsert failed");                Err(())            }        }    }    /// Send a pairing reply message to the sender (async helper for spawned task).    async fn send_pairing_reply_async(        http_url: &str,        account: &str,        recipient: &str,        message: &str,    ) -> Result<(), ChannelError> {        let client = Client::builder()            .connect_timeout(Duration::from_secs(10))            .build()            .map_err(|e| ChannelError::Http(e.to_string()))?;        let target = Self::parse_recipient_target(recipient);        let params = Self::build_rpc_params_static(http_url, account, &target, Some(message), None);        let url = format!("{}/api/v1/rpc", http_url);        let id = Uuid::new_v4().to_string();        let body = serde_json::json!({            "jsonrpc": "2.0",            "method": "send",            "params": params,            "id": id,        });        let resp = client            .post(&url)            .timeout(Duration::from_secs(30))            .header("Content-Type", "application/json")            .json(&body)            .send()            .await            .map_err(|e| ChannelError::SendFailed {                name: "signal".to_string(),                reason: format!("RPC request failed to {}: {e}", Self::redact_url(&url)),            })?;        let status = resp.status();        let is_success = status.is_success();        if status.as_u16() == 201 {            return Ok(());        }        if !is_success {            let bytes = resp.bytes().await.unwrap_or_default();            let truncated_len = bytes.len().min(MAX_ERROR_LOG_BODY);            let truncated_body = String::from_utf8_lossy(&bytes[..truncated_len]);            return Err(ChannelError::SendFailed {                name: "signal".to_string(),                reason: format!("HTTP error {}: {}", status.as_u16(), truncated_body),            });        }        Ok(())    }    /// Get effective group allow_from list (inherits from allow_from if empty).    fn effective_group_allow_from(&self) -> &[String] {        if self.config.group_allow_from.is_empty() {            &self.config.allow_from        } else {            &self.config.group_allow_from        }    }    /// Check whether a group is in the allowed groups list.    ///    /// - Empty list — deny all groups (DMs only, secure by default).    /// - `*` — allow all groups.    /// - Specific IDs — allow only those groups.    fn is_group_allowed(&self, group_id: &str) -> bool {        if self.config.allow_from_groups.is_empty() {            return false;        }        self.config            .allow_from_groups            .iter()            .any(|entry| entry == "*" || entry == group_id)    }    /// Check whether a sender is allowed for group messages.    fn is_group_sender_allowed(&self, sender: &str) -> bool {        let effective_list = self.effective_group_allow_from();        if effective_list.is_empty() {            return false;        }        effective_list.iter().any(|entry| {            entry == "*"                || Self::normalize_allow_entry(entry) == Self::normalize_allow_entry(sender)        })    }    /// Redact credentials from a URL for safe logging.    ///    /// Replaces any embedded username/password with `**REDACTED**` and returns    /// the sanitised string. Returns `"<invalid-url>"` when parsing fails.    pub fn redact_url(url: &str) -> String {        reqwest::Url::parse(url)            .map(|mut u| {                if u.password().is_some() || !u.username().is_empty() {                    let _ = u.set_username("**REDACTED**");                    let _ = u.set_password(None);                }                u.to_string()            })            .unwrap_or_else(|_| "<invalid-url>".to_string())    }    fn is_e164(recipient: &str) -> bool {        let Some(number) = recipient.strip_prefix('+') else {            return false;        };        (7..=15).contains(&number.len()) && number.chars().all(|c| c.is_ascii_digit())    }    /// Check whether a string is a valid UUID (signal-cli uses these for    /// privacy-enabled users who have opted out of sharing their phone number).    fn is_uuid(s: &str) -> bool {        Uuid::parse_str(s).is_ok()    }    /// Generate a deterministic UUID from an identifier (phone number or group ID).    ///    /// This ensures that the same phone number or group always produces the same UUID,    /// allowing conversation history to persist across gateway restarts.    fn thread_id_from_identifier(identifier: &str) -> String {        // Use a stable, deterministic UUID v5 derived from the identifier.        // This avoids relying on `DefaultHasher` implementation details and        // provides a full 128 bits of entropy.        Uuid::new_v5(&Uuid::NAMESPACE_URL, identifier.as_bytes()).to_string()    }    fn parse_recipient_target(recipient: &str) -> RecipientTarget {        if let Some(group_id) = recipient.strip_prefix(GROUP_TARGET_PREFIX) {            return RecipientTarget::Group(group_id.to_string());        }        if Self::is_e164(recipient) || Self::is_uuid(recipient) {            RecipientTarget::Direct(recipient.to_string())        } else {            RecipientTarget::Group(recipient.to_string())        }    }    /// Determine the reply target: group id (prefixed) or the sender's identifier.    fn reply_target(data_msg: &DataMessage, sender: &str) -> String {        if let Some(group_id) = data_msg            .group_info            .as_ref()            .and_then(|g| g.group_id.as_deref())        {            format!("{GROUP_TARGET_PREFIX}{group_id}")        } else {            sender.to_string()        }    }    /// Send a JSON-RPC request to signal-cli daemon.    async fn rpc_request(        &self,        method: &str,        params: serde_json::Value,    ) -> Result<Option<serde_json::Value>, ChannelError> {        let url = format!("{}/api/v1/rpc", self.config.http_url);        let id = Uuid::new_v4().to_string();        let body = serde_json::json!({            "jsonrpc": "2.0",            "method": method,            "params": params,            "id": id,        });        let resp = self            .client            .post(&url)            .timeout(Duration::from_secs(30))            .header("Content-Type", "application/json")            .json(&body)            .send()            .await            .map_err(|e| ChannelError::SendFailed {                name: "signal".to_string(),                reason: format!("RPC request failed to {}: {e}", Self::redact_url(&url)),            })?;        // 201 = success with no body (e.g. typing indicators).        if resp.status().as_u16() == 201 {            return Ok(None);        }        // Reject obviously oversized responses before buffering.        if let Some(len) = resp.content_length()            && len as usize > MAX_HTTP_RESPONSE_SIZE        {            return Err(ChannelError::SendFailed {                name: "signal".to_string(),                reason: format!(                    "RPC response Content-Length too large: {} bytes (max {})",                    len, MAX_HTTP_RESPONSE_SIZE                ),            });        }        let status = resp.status();        let mut stream = resp.bytes_stream();        let mut total_bytes = 0usize;        let mut body = Vec::new();        while let Some(chunk) = stream.next().await {            let chunk = chunk.map_err(|e| ChannelError::SendFailed {                name: "signal".to_string(),                reason: format!("Failed to read RPC response: {e}"),            })?;            let chunk_len = chunk.len();            total_bytes += chunk_len;            if total_bytes > MAX_HTTP_RESPONSE_SIZE {                return Err(ChannelError::SendFailed {                    name: "signal".to_string(),                    reason: format!(                        "RPC response too large: {} bytes (max {})",                        total_bytes, MAX_HTTP_RESPONSE_SIZE                    ),                });            }            body.extend_from_slice(&chunk);        }        let bytes = body;        if bytes.is_empty() {            return Ok(None);        }        // Check for non-success HTTP status codes before parsing as JSON.        if !status.is_success() {            let truncated_len = std::cmp::min(bytes.len(), 512);            let truncated_body = String::from_utf8_lossy(&bytes[..truncated_len]);            return Err(ChannelError::SendFailed {                name: "signal".to_string(),                reason: format!("HTTP error {}: {}", status.as_u16(), truncated_body),            });        }        let parsed: serde_json::Value =            serde_json::from_slice(&bytes).map_err(|e| ChannelError::SendFailed {                name: "signal".to_string(),                reason: format!("Invalid RPC response JSON: {e}"),            })?;        if let Some(err) = parsed.get("error") {            let code = err.get("code").and_then(|c| c.as_i64()).unwrap_or(-1);            let msg = err                .get("message")                .and_then(|m| m.as_str())                .unwrap_or("unknown");            return Err(ChannelError::SendFailed {                name: "signal".to_string(),                reason: format!("Signal RPC error {code}: {msg}"),            });        }        Ok(parsed.get("result").cloned())    }    /// Build JSON-RPC params for a send/typing call.    fn build_rpc_params(        &self,        target: &RecipientTarget,        message: Option<&str>,        attachments: Option<&[String]>,    ) -> serde_json::Value {        match target {            RecipientTarget::Direct(id) => {                let mut params = serde_json::json!({                    "recipient": [id],                    "account": &self.config.account,                });                if let Some(msg) = message {                    params["message"] = serde_json::Value::String(msg.to_string());                }                if let Some(attachments) = attachments                    && !attachments.is_empty()                {                    params["attachments"] = serde_json::Value::Array(                        attachments                            .iter()                            .map(|s| serde_json::Value::String(s.clone()))                            .collect(),                    );                }                params            }            RecipientTarget::Group(group_id) => {                let mut params = serde_json::json!({                    "groupId": group_id,                    "account": &self.config.account,                });                if let Some(msg) = message {                    params["message"] = serde_json::Value::String(msg.to_string());                }                if let Some(attachments) = attachments                    && !attachments.is_empty()                {                    params["attachments"] = serde_json::Value::Array(                        attachments                            .iter()                            .map(|s| serde_json::Value::String(s.clone()))                            .collect(),                    );                }                params            }        }    }    /// Validate that attachment paths are safe and within the sandbox.    /// Uses the shared path validation logic from path_utils to ensure:    /// - No path traversal attacks (../, URL-encoded, null bytes)    /// - Paths are canonicalized and symlinks resolved    /// - All paths are within ~/.ironclaw/ sandbox    fn validate_attachment_paths(paths: &[String]) -> Result<(), ChannelError> {        // Get the sandbox base directory (same as MessageTool uses)        let base_dir = ironclaw_base_dir();        for path in paths {            crate::tools::builtin::path_utils::validate_path(path, Some(&base_dir)).map_err(                |e| {                    ChannelError::InvalidMessage(format!(                        "Attachment path must be within {}: {}",                        base_dir.display(),                        e                    ))                },            )?;        }        Ok(())    }    /// Send a message with attachments (if any).    /// Combines text and attachments into a single RPC call when both are present.    async fn send_with_attachments(        &self,        target: &RecipientTarget,        content: &str,        attachments: &[String],    ) -> Result<(), ChannelError> {        Self::validate_attachment_paths(attachments)?;        if attachments.is_empty() {            let params = self.build_rpc_params(target, Some(content), None);            self.rpc_request("send", params).await?;        } else if content.is_empty() {            // Attachments only - send all in a single call with no message text            let params = self.build_rpc_params(target, None, Some(attachments));            self.rpc_request("send", params).await?;        } else {            // Both text and attachments - send in a single RPC call            let params = self.build_rpc_params(target, Some(content), Some(attachments));            self.rpc_request("send", params).await?;        }        Ok(())    }    /// Build JSON-RPC params for a send/typing call (static version).    fn build_rpc_params_static(        _http_url: &str,        account: &str,        target: &RecipientTarget,        message: Option<&str>,        attachments: Option<&[String]>,    ) -> serde_json::Value {        match target {            RecipientTarget::Direct(id) => {                let mut params = serde_json::json!({                    "recipient": [id],                    "account": account,                });                if let Some(msg) = message {                    params["message"] = serde_json::Value::String(msg.to_string());                }                if let Some(attachments) = attachments                    && !attachments.is_empty()                {                    params["attachments"] = serde_json::Value::Array(                        attachments                            .iter()                            .map(|s| serde_json::Value::String(s.clone()))                            .collect(),                    );                }                params            }            RecipientTarget::Group(group_id) => {                let mut params = serde_json::json!({                    "groupId": group_id,                    "account": account,                });                if let Some(msg) = message {                    params["message"] = serde_json::Value::String(msg.to_string());                }                if let Some(attachments) = attachments                    && !attachments.is_empty()                {                    params["attachments"] = serde_json::Value::Array(                        attachments                            .iter()                            .map(|s| serde_json::Value::String(s.clone()))                            .collect(),                    );                }                params            }        }    }    /// Process a single SSE envelope, returning an `IncomingMessage` if valid.    fn process_envelope(&self, envelope: &Envelope) -> Option<(IncomingMessage, String)> {        // Skip story messages when configured.        if self.config.ignore_stories && envelope.story_message.is_some() {            tracing::debug!("Signal: dropping story message");            return None;        }        let data_msg = envelope.data_message.as_ref()?;        // Skip attachment-only messages when configured.        let has_attachments = data_msg.attachments.as_ref().is_some_and(|a| !a.is_empty());        let has_message_text = data_msg.message.as_ref().is_some_and(|m| !m.is_empty());        if self.config.ignore_attachments && has_attachments && !has_message_text {            tracing::debug!("Signal: dropping attachment-only message");            return None;        }        // Use message text, or fall back to "[Attachment]" for attachment-only messages        // when ignore_attachments is false. This ensures attachment-only messages are        // still processed when the user wants them (rather than always being dropped).        let text = data_msg            .message            .as_deref()            .filter(|t| !t.is_empty())            .map(String::from)            .or_else(|| {                if has_attachments {                    Some("[Attachment]".to_string())                } else {                    None                }            })?;        let sender = Self::sender(envelope)?;        // Log sender info including UUID if available        tracing::debug!(            sender = %sender,            uuid = ?envelope.source_uuid,            "Signal: received message"        );        // Check if this is a group message        let is_group = data_msg            .group_info            .as_ref()            .and_then(|g| g.group_id.as_deref())            .is_some();        // Apply group policy first (before DM policy for group messages)        if is_group {            match self.config.group_policy.as_str() {                "disabled" => {                    tracing::debug!("Signal: group messages disabled, dropping");                    return None;                }                "open" => {                    // For "open" policy, check group allowlist but not sender allowlist                    if let Some(group_id) = data_msg                        .group_info                        .as_ref()                        .and_then(|g| g.group_id.as_deref())                        && !self.is_group_allowed(group_id)                    {                        tracing::debug!(                            group_id = %group_id,                            "Signal: group not in allow_from_groups, dropping"                        );                        return None;                    }                }                "allowlist" => {                    // Default to allowlist - check group AND sender                    if let Some(group_id) = data_msg                        .group_info                        .as_ref()                        .and_then(|g| g.group_id.as_deref())                    {                        if !self.is_group_allowed(group_id) {                            tracing::debug!(                                group_id = %group_id,                                "Signal: group not in allow_from_groups, dropping"                            );                            return None;                        }                        // Also check sender is allowed for group                        if !self.is_group_sender_allowed(&sender) {                            tracing::debug!(                                sender = %sender,                                group_id = %group_id,                                "Signal: sender not in group_allow_from, dropping"                            );                            return None;                        }                    }                }                _ => {}            }        } else {            // DM message - apply DM policy            match self.config.dm_policy.as_str() {                "open" => {}                "pairing" => {                    // Pairing policy: check allow_from + pairing store                    if !self.is_sender_allowed_with_pairing(&sender) {                        // Handle pairing request - this will create a request and send reply if new                        match self.handle_pairing_request(&sender, envelope.source_name.as_deref())                        {                            Ok(_) => {                                // Pairing request processed (new or existing), drop the message                                return None;                            }                            Err(()) => {                                // Error processing pairing, drop message                                return None;                            }                        }                    }                }                "allowlist" => {                    // Default: check allow_from list                    if !self.is_sender_allowed(&sender) {                        tracing::debug!(sender = %sender, "Signal: sender not in allow_from, dropping");                        return None;                    }                }                _ => {}            }        }        let target = Self::reply_target(data_msg, &sender);        let timestamp = data_msg            .timestamp            .or(envelope.timestamp)            .unwrap_or_else(|| {                u64::try_from(                    std::time::SystemTime::now()                        .duration_since(std::time::UNIX_EPOCH)                        .unwrap_or_default()                        .as_millis(),                )                .unwrap_or(u64::MAX)            });        // Build metadata with signal-specific routing info.        let sender_uuid = envelope.source_uuid.as_deref();        let metadata = serde_json::json!({            "signal_sender": &sender,            "signal_sender_uuid": sender_uuid,            "signal_target": &target,            "signal_timestamp": timestamp,        });        let mut msg = IncomingMessage::new("signal", &sender, text).with_metadata(metadata);        // Use sourceName as display name if available.        if let Some(ref name) = envelope.source_name            && !name.is_empty()        {            msg = msg.with_user_name(name);        }        // Use a deterministic UUID as thread_id for all conversations.        // This ensures DMs and groups continue the same thread AND work with        // maybe_hydrate_thread, enabling conversation history persistence.        // Priority: source_uuid > generated UUID from phone/group        if data_msg.group_info.is_some() {            // For groups, use the group ID to generate a deterministic UUID            msg = msg.with_thread(Self::thread_id_from_identifier(&target));        } else if let Some(ref uuid) = envelope.source_uuid {            // Privacy mode users already have a UUID            msg = msg.with_thread(uuid.clone());        } else {            // For regular DMs, generate a deterministic UUID from the phone number            msg = msg.with_thread(Self::thread_id_from_identifier(&sender));        }        Some((msg, target))    }}#[async_trait]impl Channel for SignalChannel {    fn name(&self) -> &str {        "signal"    }    async fn start(&self) -> Result<MessageStream, ChannelError> {        let (tx, rx) = tokio::sync::mpsc::channel(256);        let config = self.config.clone();        let client = self.client.clone();        let reply_targets = Arc::clone(&self.reply_targets);        let debug_mode = Arc::clone(&self.debug_mode);        tokio::spawn(async move {            if let Err(e) = sse_listener(config, client, tx, reply_targets, debug_mode).await {                tracing::error!("Signal SSE listener exited with error: {e}");            }        });        // Log the URL with credentials redacted (if any).        let safe_url = Self::redact_url(&self.config.http_url);        tracing::info!(            url = %safe_url,            "Signal channel started"        );        Ok(Box::pin(tokio_stream::wrappers::ReceiverStream::new(rx)))    }    async fn respond(        &self,        msg: &IncomingMessage,        response: OutgoingResponse,    ) -> Result<(), ChannelError> {        // Resolve reply target from stored metadata.        let target_str = {            let targets = self.reply_targets.read().await;            targets.peek(&msg.id).cloned()        }        .or_else(|| {            // Fall back to metadata if not in the map.            msg.metadata                .get("signal_target")                .and_then(|v| v.as_str())                .map(String::from)        })        .unwrap_or_else(|| msg.user_id.clone());        let target = Self::parse_recipient_target(&target_str);        // Use shared helper for sending with attachments (includes validation)        let result = self            .send_with_attachments(&target, &response.content, &response.attachments)            .await;        // Clean up stored target regardless of success or failure.        self.reply_targets.write().await.pop(&msg.id);        result    }    async fn send_status(        &self,        status: StatusUpdate,        metadata: &serde_json::Value,    ) -> Result<(), ChannelError> {        // Send typing indicator for thinking status.        if matches!(status, StatusUpdate::Thinking(_))            && let Some(target_str) = metadata.get("signal_target").and_then(|v| v.as_str())        {            let target = Self::parse_recipient_target(target_str);            let params = self.build_rpc_params(&target, None, None);            let _ = self.rpc_request("sendTyping", params).await;        }        // Send approval prompt to user        if let StatusUpdate::ApprovalNeeded {            request_id,            tool_name,            description: _,            parameters,        } = &status            && let Some(target_str) = metadata.get("signal_target").and_then(|v| v.as_str())        {            let params_json = serde_json::to_string_pretty(parameters).unwrap_or_default();            let message = format!(                "⚠️ *Approval Required*\n\n\                 *Request ID:* `{}`\n\                 *Tool:* {}\n\                 *Parameters:*\n```\n{}\n```\n\n\                 Reply with:\n\                 • `yes` or `y` - Approve this request\n\                 • `always` or `a` - Approve and auto-approve future {} requests\n\                 • `no` or `n` - Deny",                request_id, tool_name, params_json, tool_name            );            self.send_status_message(target_str, &message).await;        }        // Filter out well-known UX/terminal status messages to avoid redundant updates.        let should_forward_status = |msg: &str| {            let normalized = msg.trim();            !normalized.eq_ignore_ascii_case("done")                && !normalized.eq_ignore_ascii_case("awaiting approval")                && !normalized.eq_ignore_ascii_case("rejected")        };        // Filter/send status messages        if let StatusUpdate::Status(msg) = &status            && let Some(target_str) = metadata.get("signal_target").and_then(|v| v.as_str())            && should_forward_status(msg)        {            self.send_status_message(target_str, msg).await;        }        // Send tool result previews to user (debug mode only)        if self.is_debug()            && let StatusUpdate::ToolResult { name, preview } = &status            && let Some(target_str) = metadata.get("signal_target").and_then(|v| v.as_str())        {            let truncated = if preview.chars().count() > 500 {                let s: String = preview.chars().take(500).collect();                format!("{s}...")            } else {                preview.clone()            };            let message = format!("Tool '{}' result:\n{}", name, truncated);            self.send_status_message(target_str, &message).await;        }        // Send tool started notification (debug mode only)        if self.is_debug()            && let StatusUpdate::ToolStarted { name } = &status            && let Some(target_str) = metadata.get("signal_target").and_then(|v| v.as_str())        {            let message = format!("\u{25CB} Running tool: {}", name);            self.send_status_message(target_str, &message).await;        }        // Send tool completed notification (debug mode only)        if self.is_debug()            && let StatusUpdate::ToolCompleted { name, success, .. } = &status            && let Some(target_str) = metadata.get("signal_target").and_then(|v| v.as_str())        {            let (icon, color) = if *success {                ("\u{25CF}", "success")            } else {                ("\u{2717}", "failed")            };            let message = format!("{} Tool '{}' completed ({})", icon, name, color);            self.send_status_message(target_str, &message).await;        }        // Send job started notification (sandbox jobs)        if let StatusUpdate::JobStarted {            job_id,            title,            browse_url,        } = &status            && let Some(target_str) = metadata.get("signal_target").and_then(|v| v.as_str())        {            let message = format!(                "\u{1F680} Job started: {}\nID: {}\nURL: {}",                title, job_id, browse_url            );            self.send_status_message(target_str, &message).await;        }        // Send auth required notification        if let StatusUpdate::AuthRequired {            extension_name,            instructions,            auth_url,            setup_url,        } = &status            && let Some(target_str) = metadata.get("signal_target").and_then(|v| v.as_str())        {            let mut message = format!("\u{1F512} Authentication required for: {}", extension_name);            if let Some(instr) = instructions {                message.push_str(&format!("\n\n{}", instr));            }            if let Some(url) = auth_url {                message.push_str(&format!("\n\nAuth URL: {}", url));            }            if let Some(url) = setup_url {                message.push_str(&format!("\nSetup URL: {}", url));            }            self.send_status_message(target_str, &message).await;        }        // Send auth completed notification        if let StatusUpdate::AuthCompleted {            extension_name,            success,            message: msg,        } = &status            && let Some(target_str) = metadata.get("signal_target").and_then(|v| v.as_str())        {            let icon = if *success { "\u{2705}" } else { "\u{274C}" };            let mut message = format!(                "{} Authentication {} for {}",                icon,                if *success { "completed" } else { "failed" },                extension_name            );            if !msg.is_empty() {                message.push_str(&format!("\n{}", msg));            }            self.send_status_message(target_str, &message).await;        }        Ok(())    }    async fn broadcast(        &self,        user_id: &str,        response: OutgoingResponse,    ) -> Result<(), ChannelError> {        let target = Self::parse_recipient_target(user_id);        // Use shared helper for sending with attachments (includes validation)        self.send_with_attachments(&target, &response.content, &response.attachments)            .await    }    async fn health_check(&self) -> Result<(), ChannelError> {        let url = format!("{}{}", self.config.http_url, SIGNAL_HEALTH_ENDPOINT);        let resp = self            .client            .get(&url)            .timeout(Duration::from_secs(10))            .send()            .await            .map_err(|e| ChannelError::HealthCheckFailed {                name: format!("signal ({}): {e}", Self::redact_url(&url)),            })?;        if resp.status().is_success() {            Ok(())        } else {            Err(ChannelError::HealthCheckFailed {                name: format!("signal: HTTP {}", resp.status()),            })        }    }    fn conversation_context(        &self,        metadata: &serde_json::Value,    ) -> std::collections::HashMap<String, String> {        use std::collections::HashMap;        let mut ctx = HashMap::new();        if let Some(sender) = metadata.get("signal_sender").and_then(|v| v.as_str()) {            ctx.insert("sender".to_string(), sender.to_string());        }        if let Some(sender_uuid) = metadata.get("signal_sender_uuid").and_then(|v| v.as_str()) {            ctx.insert("sender_uuid".to_string(), sender_uuid.to_string());        }        if let Some(target) = metadata.get("signal_target").and_then(|v| v.as_str())            && target.starts_with("group:")        {            ctx.insert("group".to_string(), target.to_string());        }        ctx    }}impl SignalChannel {    async fn send_status_message(&self, target: &str, message: &str) {        let target = Self::parse_recipient_target(target);        let params = self.build_rpc_params(&target, Some(message), None);        if let Err(e) = self.rpc_request("send", params).await {            tracing::warn!("Signal: failed to send status message: {}", e);        }    }}/// Long-running SSE listener that reconnects with exponential backoff.